#!/usr/bin/env bash
# Ship Framework — design gate, after shell commands (PostToolUse on Bash)
#
# check-refgate.sh runs BEFORE Edit/Write and can refuse them. A shell command — sed -i, a Python
# script, a heredoc — writes files without passing through it. This hook runs AFTER each Bash call
# and reports what the gate would have refused. It DETECTS; it can't undo or prevent:
#   - a generated file (header "Generated by Ship") that differs from what design-model.yaml emits
#     (re-emitted to a temp file and compared) — a hand edit the next emit would silently lose;
#   - a new UI/motion/copy file created in a Ship project without the design contract.
# Coverage limits (say so, don't pretend): git projects only; compares against the last commit
# (staged and unstaged changes, untracked files), so a write reverted in the same command, a file
# outside the project, an ignored file, or a change committed within the same command isn't seen;
# a problem is reported once per file version.
#
# Output: nothing when clean; otherwise a PostToolUse block reason the agent sees. Fails quiet.

set -uo pipefail
ROOT="${CLAUDE_PROJECT_DIR:-.}"
cd "$ROOT" 2>/dev/null || exit 0
ROOT="$(pwd -P)"
cat >/dev/null 2>&1 || true                              # hook input isn't needed
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || exit 0

HERE="$(cd "$(dirname "$0")" && pwd)"
GATE="$HERE/check-refgate.sh"
DM=""
for c in "$HERE/../../design/bin/design_model.py" "$HERE/../../ship-design/bin/design_model.py"; do
  [ -f "$c" ] && { DM="$c"; break; }
done
SEEN="${TMPDIR:-/tmp}/ship-after-shell-$(printf '%s' "$ROOT" | cksum | cut -d' ' -f1)"
touch "$SEEN" 2>/dev/null || SEEN=/dev/null

new_problem() {                                         # report each file version once
  local key="$1|$(cksum < "$1" 2>/dev/null | cut -d' ' -f1)"
  grep -qxF "$key" "$SEEN" 2>/dev/null && return 1
  echo "$key" >> "$SEEN" 2>/dev/null; return 0
}

PROBLEMS=""
# Every path that differs from the last commit — staged or not — plus untracked files, once each.
# (`git ls-files -m -o` missed edits staged in the same command.) No commit yet → everything is new.
if git rev-parse -q --verify HEAD >/dev/null 2>&1; then
  CHANGED="$( { git diff --name-only --no-renames HEAD --; git ls-files -o --exclude-standard; } 2>/dev/null | sort -u | head -300)"
  in_head() { git cat-file -e "HEAD:$1" 2>/dev/null; }
else
  CHANGED="$( { git ls-files; git ls-files -o --exclude-standard; } 2>/dev/null | sort -u | head -300)"
  in_head() { return 1; }
fi
VERIFIED=""                                             # generated files that match the emitter

# 1. Generated files changed by hand: re-emit the same target to a temp file and compare.
#    (A shell `emit` produces exactly this output; a hand edit doesn't.)
target_of() {
  local t; t="$(head -5 "$1" | grep -o 'target=[a-z_]*' | head -1 | cut -d= -f2)"
  [ -n "$t" ] && { echo "$t"; return; }
  case "$1" in
    *COMPONENTS.md) echo docs ;; *.swift) echo swiftui ;; *.kt) echo compose ;; *.css) echo css ;; *) echo "" ;;
  esac
}
if [ -n "$DM" ] && [ -f design-model.yaml ]; then
  WORK="$(mktemp -d 2>/dev/null)" || WORK=""
  while IFS= read -r f; do
    [ -n "$f" ] && [ -f "$f" ] && [ -n "$WORK" ] || continue
    head -5 "$f" 2>/dev/null | grep -q "Generated by Ship\|ship-generated:" || continue
    T="$(target_of "$f")"; OUTF="$WORK/$(basename "$f")"
    if [ "$T" = docs ]; then python3 "$DM" docs --root "$ROOT" --out "$OUTF" >/dev/null 2>&1
    elif [ -n "$T" ]; then python3 "$DM" emit "$T" --root "$ROOT" --out "$OUTF" >/dev/null 2>&1
    fi
    if [ -f "$OUTF" ] && cmp -s "$OUTF" "$f"; then VERIFIED="$VERIFIED$f"$'\n'; continue; fi
    new_problem "$f" || continue
    if [ -f "$OUTF" ]; then
      PROBLEMS="$PROBLEMS- $f (generated) was changed by a shell command and doesn't match what design-model.yaml emits — the next emit will overwrite it. Revert it, change design-model.yaml, and re-emit.\n"
    else
      PROBLEMS="$PROBLEMS- $f (generated) was changed by a shell command and couldn't be re-emitted to compare — check it wasn't hand-edited.\n"
    fi
  done <<< "$CHANGED"
  [ -n "$WORK" ] && rm -rf "$WORK"
fi

# 2. New files (not in the last commit, staged or not) the gate would have refused. A file that
#    matched the emitter above is the design model's output, not invented UI — never re-judged here;
#    a generated file that didn't match was already reported above.
while IFS= read -r f; do
  [ -n "$f" ] && [ -f "$f" ] || continue
  in_head "$f" && continue                                               # existed before → not new
  printf '%s' "$VERIFIED" | grep -qxF "$f" && continue
  head -5 "$f" 2>/dev/null | grep -q "Generated by Ship\|ship-generated:" && continue
  V="$(printf '{"tool_input":{"file_path":"%s"}}' "$ROOT/$f" | REFGATE_ASSUME_NEW=1 CLAUDE_PROJECT_DIR="$ROOT" bash "$GATE" 2>/dev/null)"
  case "$V" in *'"deny"'*) new_problem "$f" && PROBLEMS="$PROBLEMS- $f: created by a shell command; the design gate would have refused it — $(printf '%s' "$V" | sed 's/.*"permissionDecisionReason":"//; s/"}}$//')\n" ;; esac
done <<< "$CHANGED"

[ -n "$PROBLEMS" ] || exit 0
MSG="Ship design gate, after the fact (a shell command bypassed the pre-edit check):\n$PROBLEMS"
MSG_JSON="$(printf '%b' "$MSG" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))')"
printf '{"decision":"block","reason":%s,"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":%s}}\n' "$MSG_JSON" "$MSG_JSON"
exit 0
